<script setup lang="ts">
import { ArrowLeft, CreditCard, Plus, Save, ShieldCheck, X } from '@lucide/vue'
import { onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import api from '../api'
import BrandLogo from '../components/BrandLogo.vue'
import PlatformSidebar from '../components/PlatformSidebar.vue'
const router=useRouter();const plans=ref<any[]>([]);const loading=ref(true);const createOpen=ref(false);const message=ref('');const error=ref('');const saving=ref<number|null>(null);const newPlan=reactive({slug:'',name:'',description:'',monthly_price_minor:0,yearly_price_minor:0,centre_limit:1,student_limit:100,staff_limit:2,group_limit:10,features:''});const paymob=reactive({secret_key:'',public_key:'',hmac_secret:'',iframe_id:'',payment_methods:'',api_base:'https://accept.paymob.com',checkout_base:'https://accept.paymob.com/unifiedcheckout'});const paymobSaving=ref(false)
async function load(){const [p,g]=await Promise.all([api.get('/platform/plans'),api.get('/platform/paymob-settings')]);plans.value=p.data.plans;Object.assign(paymob,{payment_methods:g.data.payment_methods.join(','),iframe_id:g.data.iframe_id||'',api_base:g.data.api_base,checkout_base:g.data.checkout_base});loading.value=false}
async function savePlan(plan:any){saving.value=plan.id;try{await api.patch(`/platform/plans/${plan.id}`,{...plan,features:Array.isArray(plan.features)?plan.features:[]});message.value='Plan saved.'}catch(e:any){error.value=e.response?.data?.message||'Unable to save plan.'}finally{saving.value=null}}
async function createPlan(){try{const response=await api.post('/platform/plans',{...newPlan,features:newPlan.features.split('\n').filter(Boolean)});plans.value.push(response.data.plan);createOpen.value=false;message.value='Plan created.'}catch(e:any){error.value=e.response?.data?.message||'Unable to create plan.'}}
async function savePaymob(){paymobSaving.value=true;try{await api.put('/platform/paymob-settings',{...paymob,payment_methods:paymob.payment_methods.split(',').map(Number).filter(Boolean)});message.value='Paymob settings saved.'}catch(e:any){error.value=e.response?.data?.message||'Unable to save Paymob settings.'}finally{paymobSaving.value=false}}
onMounted(load)
</script>
<template>
<PlatformSidebar/>
<div class="platform-settings-page"><header><BrandLogo/><button class="button secondary" @click="router.push('/admin/settings')"><ArrowLeft/>Back to platform settings</button></header><main><div class="settings-hero"><div><span>PLATFORM COMMERCIAL CONTROL</span><h1>Plans & payments</h1><p>Manage trial access, plan limits and Paymob billing.</p></div><button class="button primary" @click="createOpen=true"><Plus/>Add plan</button><ShieldCheck/></div>
<div v-if="loading" class="loading-state">Loading commercial settings…</div><template v-else><div v-if="message" class="settings-message">{{message}}</div><div v-if="error" class="form-error">{{error}}</div><section class="plan-editor-grid"><article v-for="plan in plans" :key="plan.id" class="plan-editor"><div class="plan-editor-head"><div><span>PLAN {{plan.position}}</span><h2>{{plan.name}}</h2></div><em :class="plan.is_active?'active':'pending'">{{plan.is_active?'Active':'Hidden'}}</em></div><label>Name<input v-model="plan.name"></label><label>Description<textarea v-model="plan.description" rows="2"></textarea></label><div class="plan-fields"><label>Monthly EGP<input v-model.number="plan.monthly_price_minor" type="number"></label><label>Yearly EGP<input v-model.number="plan.yearly_price_minor" type="number"></label><label>Centres<input v-model.number="plan.centre_limit" type="number"></label><label>Students<input v-model.number="plan.student_limit" type="number"></label><label>Staff<input v-model.number="plan.staff_limit" type="number"></label><label>Groups<input v-model.number="plan.group_limit" type="number"></label></div><div class="plan-actions"><label class="check-label"><input v-model="plan.is_active" type="checkbox"> Active</label><label class="check-label"><input v-model="plan.is_featured" type="checkbox"> Featured</label><button class="button primary" :disabled="saving===plan.id" @click="savePlan(plan)"><Save/>Save plan</button></div></article></section><section class="paymob-editor"><div class="settings-card-head"><CreditCard/><div><small>PAYMOB GATEWAY</small><h2>Egyptian checkout connection</h2></div></div><div class="paymob-fields"><label>Secret key<input v-model="paymob.secret_key" type="password"></label><label>Public key<input v-model="paymob.public_key" type="password"></label><label>HMAC secret<input v-model="paymob.hmac_secret" type="password"></label><label>Iframe ID<input v-model="paymob.iframe_id"></label><label>Payment method IDs<input v-model="paymob.payment_methods"></label><label>API base<input v-model="paymob.api_base"></label><label>Checkout base<input v-model="paymob.checkout_base"></label></div><button class="button primary" @click="savePaymob" :disabled="paymobSaving"><CreditCard/>Save Paymob settings</button></section></template></main>
<div v-if="createOpen" class="modal-backdrop" @click.self="createOpen=false"><section class="centre-modal plan-create-modal"><button class="modal-close" @click="createOpen=false"><X/></button><span class="modal-icon"><Plus/></span><h2>Add subscription plan</h2><form @submit.prevent="createPlan"><label>Slug<input v-model="newPlan.slug" required placeholder="pro"></label><label>Name<input v-model="newPlan.name" required></label><label>Description<textarea v-model="newPlan.description"></textarea></label><div class="plan-fields"><label>Monthly EGP<input v-model.number="newPlan.monthly_price_minor" type="number"></label><label>Yearly EGP<input v-model.number="newPlan.yearly_price_minor" type="number"></label><label>Centres<input v-model.number="newPlan.centre_limit" type="number"></label><label>Students<input v-model.number="newPlan.student_limit" type="number"></label><label>Staff<input v-model.number="newPlan.staff_limit" type="number"></label><label>Groups<input v-model.number="newPlan.group_limit" type="number"></label></div><label>Features<textarea v-model="newPlan.features" rows="4"></textarea></label><div class="modal-actions"><button type="button" class="button secondary" @click="createOpen=false">Cancel</button><button class="button primary"><Plus/>Create plan</button></div></form></section></div></div>
</template>
